// V5 WID — anonymous visitor identity + session for the marketing support widget (brief §9–10).
//  * Identity: widget_visitors.id is a random uuid generated by the database; nothing about it derives from the name or
//    email a visitor types, and it never leaves the server (the browser only holds an opaque session token).
//  * Session: 32 random bytes in an HttpOnly cookie (Secure + __Host- prefix in production, SameSite=Lax); only the
//    SHA-256 is stored. Absolute lifetime WIDGET_SESSION_TTL_DAYS, idle timeout WIDGET_SESSION_IDLE_DAYS; revocable by
//    the visitor ("End chat on this device"). Each session has its own CSRF token, required on every visitor mutation
//    together with an Origin check (apps/web/app/api/widget/_lib.ts).
//  * verified_email is written ONLY by the one-time verification flow (widget-verify.ts). Typing an email never sets it.
//  * Form token: a server-signed issue time used as a time trap against automated first messages.
import { createHmac, timingSafeEqual } from 'node:crypto';
import { AppError } from '@social-lite/core';
import { WIDGET_FORM_TOKEN_TTL_MS, WIDGET_MIN_FILL_MS, WIDGET_SESSION_IDLE_DAYS, WIDGET_SESSION_TTL_DAYS } from '@social-lite/core/contracts/v5-widget';
import { getPool, maybeOne, one, type Queryable } from '@social-lite/db';
import { randomToken, sha256 } from '../auth/session.js';
import { config } from '../config.js';

export const WIDGET_COOKIE = process.env.APP_ENV === 'production' ? '__Host-relay_widget' : 'relay_widget';
const TOUCH_INTERVAL_MS = 60_000;

export interface WidgetSession {
  id: string;
  visitorId: string;
  csrfToken: string;
  verifiedEmail: string | null;
  expiresAt: Date;
  visitor: { name: string | null; email: string | null; blocked: boolean };
}

interface Row {
  id: string; visitor_id: string; csrf_token: string; verified_email: string | null; expires_at: Date; last_seen_at: Date;
  name: string | null; contact_email: string | null; blocked_at: Date | null;
}

const toSession = (r: Row): WidgetSession => ({
  id: r.id, visitorId: r.visitor_id, csrfToken: r.csrf_token, verifiedEmail: r.verified_email, expiresAt: r.expires_at,
  visitor: { name: r.name, email: r.contact_email, blocked: !!r.blocked_at },
});

/** Resolve the cookie token to a live session (null when missing, unknown, revoked, expired or idle too long). */
export async function resolveWidgetSession(token: string | null | undefined, db: Queryable = getPool()): Promise<WidgetSession | null> {
  if (!token || token.length < 20 || token.length > 200) return null;
  const r = await maybeOne<Row>(db,
    `SELECT s.id, s.visitor_id, s.csrf_token, s.verified_email::text AS verified_email, s.expires_at, s.last_seen_at,
            v.name, v.contact_email::text AS contact_email, v.blocked_at
       FROM widget_sessions s JOIN widget_visitors v ON v.id = s.visitor_id
      WHERE s.token_hash = $1 AND s.revoked_at IS NULL AND s.expires_at > now()`, [sha256(token)]);
  if (!r) return null;
  if (Date.now() - r.last_seen_at.getTime() > WIDGET_SESSION_IDLE_DAYS * 86_400_000) {
    await db.query(`UPDATE widget_sessions SET revoked_at=now(), revoked_reason='idle_timeout' WHERE id=$1 AND revoked_at IS NULL`, [r.id]);
    return null;
  }
  if (Date.now() - r.last_seen_at.getTime() > TOUCH_INTERVAL_MS) {
    await db.query(`UPDATE widget_sessions SET last_seen_at=now() WHERE id=$1`, [r.id]);
    await db.query(`UPDATE widget_visitors SET last_seen_at=now() WHERE id=$1`, [r.visitor_id]);
  }
  return toSession(r);
}

/** Create a new visitor identity (random uuid) — contact details as typed, unverified. */
export async function createVisitor(db: Queryable, p: { name?: string | null; email?: string | null } = {}): Promise<string> {
  const r = await one<{ id: string }>(db, `INSERT INTO widget_visitors(name, contact_email) VALUES ($1,$2) RETURNING id`, [p.name ?? null, p.email ?? null]);
  return r.id;
}

/** Open a session for a visitor; returns the cookie token (shown once, never stored). */
export async function createWidgetSession(db: Queryable, visitorId: string, verified?: { email: string } | null): Promise<{ token: string; session: WidgetSession }> {
  const token = randomToken(32);
  const csrf = randomToken(24);
  const r = await one<{ id: string; expires_at: Date }>(db,
    `INSERT INTO widget_sessions(visitor_id, token_hash, csrf_token, expires_at, verified_email, verified_at)
     VALUES ($1,$2,$3, now() + make_interval(days => $4), $5::citext, CASE WHEN $5::text IS NULL THEN NULL ELSE now() END) RETURNING id, expires_at`,
    [visitorId, sha256(token), csrf, WIDGET_SESSION_TTL_DAYS, verified?.email ?? null]);
  const v = await one<{ name: string | null; contact_email: string | null; blocked_at: Date | null }>(db,
    `SELECT name, contact_email::text AS contact_email, blocked_at FROM widget_visitors WHERE id=$1`, [visitorId]);
  return { token, session: { id: r.id, visitorId, csrfToken: csrf, verifiedEmail: verified?.email ?? null, expiresAt: r.expires_at,
    visitor: { name: v.name, email: v.contact_email, blocked: !!v.blocked_at } } };
}

/** "End chat on this device": the cookie stops working immediately. */
export async function revokeWidgetSession(db: Queryable, sessionId: string, reason = 'ended_by_visitor'): Promise<void> {
  await db.query(`UPDATE widget_sessions SET revoked_at=now(), revoked_reason=$2 WHERE id=$1 AND revoked_at IS NULL`, [sessionId, reason]);
}

/** Cookie attributes for the widget session (the route layer serialises them). */
export function widgetCookieOptions(expiresAt: Date): { httpOnly: true; secure: boolean; sameSite: 'lax'; path: '/'; expires: Date } {
  return { httpOnly: true, secure: config().APP_ENV === 'production', sameSite: 'lax', path: '/', expires: expiresAt };
}

// ------------------------------------------------------------------ form token (time trap)
function formSecret(): string {
  const s = config().SESSION_SECRET;
  if (s) return s;
  if (config().APP_ENV === 'production') throw new AppError('internal', 'SESSION_SECRET is required');
  return 'relay-widget-form-token-local-development-only';
}

const sign = (issued: number) => createHmac('sha256', formSecret()).update(`relay-widget-form:${issued}`).digest('base64url');

export function issueFormToken(now = Date.now()): string {
  return `${now}.${sign(now)}`;
}

/**
 * Time trap: the token must be genuine (HMAC), not expired, and at least WIDGET_MIN_FILL_MS old. A bot that posts the
 * form immediately (or forges a token) is refused with a generic message.
 */
export function checkFormToken(token: unknown, now = Date.now()): void {
  const generic = new AppError('validation_failed', 'Couldn’t send your message. Reload the page and try again.', { form_token: 'invalid' });
  if (typeof token !== 'string' || token.length > 120) throw generic;
  const [ts, mac] = token.split('.');
  const issued = Number(ts);
  if (!Number.isSafeInteger(issued) || !mac) throw generic;
  const expected = Buffer.from(sign(issued));
  const got = Buffer.from(mac);
  if (expected.length !== got.length || !timingSafeEqual(expected, got)) throw generic;
  if (now - issued > WIDGET_FORM_TOKEN_TTL_MS || issued - now > 60_000) {
    throw new AppError('validation_failed', 'This form has expired. Send again.', { form_token: 'expired' });
  }
  if (now - issued < WIDGET_MIN_FILL_MS) throw new AppError('validation_failed', 'Please wait a moment, then send again.', { form_token: 'too_fast' });
}
